$('#app').addEventListener('change',e=>{if(e.target.dataset.footprint){buildFootprint[e.target.dataset.footprint]=Number(e.target.value);contract(selected);return;}if(e.target.dataset.plan){setPlan(state,e.target.dataset.plan,Number(e.target.value));changed();}if(e.target.dataset.setting){const k=e.target.dataset.setting,t=state.tiles[selected];if(t?.owner==='player'){t[k]=k==='marketing'?e.target.checked:Number(e.target.value);changed();inspectAsset(selected);}}if(e.target.id==='layer')setMapLayer(e.target.value);});
$('#app').addEventListener('change',e=>{if(e.target.dataset.footprint){buildFootprint[e.target.dataset.footprint]=Number(e.target.value);contract(selected);return;}const key=e.target.dataset.mansion;if(!key||!mansionDraft)return;const input=e.target;mansionDraft[key]=input.type==='checkbox'?input.checked:['size','floors','rooms','area'].includes(key)?Number(input.value):input.value;if(key==='area')mansionDraft.area=Math.max(120,Math.min(10000,Math.round(mansionDraft.area)||120));if(key==='size'){mansionDraft.area=({1:120,2:200,3:320,4:800,5:2000})[mansionDraft.size];$('[data-mansion="area"]').value=mansionDraft.area;}mansionDraft.rooms=Math.max(2,Math.min(roomCapacity(mansionDraft),Math.round(mansionDraft.rooms)||2));const rooms=$('[data-mansion="rooms"]');rooms.max=roomCapacity(mansionDraft);rooms.value=mansionDraft.rooms;$('#mansion-capacity').textContent=`2–${roomCapacity(mansionDraft)} at this size`;$('#mansion-preview').innerHTML=mansionPreview(state,mansionDraft,analysis.wealth);});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const candidate=migrateSave(JSON.parse(await file.text()));if(!validSave(candidate))throw Error();openDialog('import',`<h2>Load this saved story?</h2><p>${esc(candidate.name)} · ${candidate.month} months in. This replaces your current auto-save.</p><button class="primary" id="confirm-import">Load</button>`);$('#confirm-import').onclick=()=>{state=candidate;ensureBasis(state);saveBlocked=false;selected=-1;renderer.select(-1);speed=0;elapsed=0;closeDialog();selectTool('inspect');changed();renderer.home();toast('Save file loaded.');};}catch{toast('Not a valid save file. Your current game is unchanged.');}finally{e.target.value='';}});
$('#dialog').addEventListener('cancel',()=>{rewardSession?.cancel();rewardSession=null;modal=null;if(dialogQueue.length)setTimeout(nextQueued,0);});
window.addEventListener('keydown',e=>{if(modal||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();speed=speed?0:1;elapsed=0;renderHUD();return;}const keys={'1':'cafe','2':'market','3':'studio',m:'pan',Escape:'inspect'};if(keys[e.key]){const v=keys[e.key];if(TYPES[v]?.group)tab=TYPES[v].group;selectTool(v);}});
window.addEventListener('beforeunload',save);
function frame(now){const dt=Math.min((now-last)/1000,.25);last=now;advanceReward(dt);if(!document.hidden&&!modal&&!state.event&&!state.shift&&speed){elapsed+=dt*speed;if(elapsed>=12){elapsed=0;month();}}renderer.render(now,elapsed/12);$('#month-progress-fill').style.width=(elapsed/12*100)+'%';const phase=elapsed<4?'☀ Morning · Customers arriving':elapsed<8?'☀ Afternoon · Open for business':'☾ Evening · Closing the month';if($('#phase-label').textContent!==phase)$('#phase-label').textContent=phase;requestAnimationFrame(frame);}
refresh();renderDock();selectTool('inspect');requestAnimationFrame(frame);
try{if(innerWidth>0&&innerWidth<720&&!localStorage.getItem('super-rich-mobile-hint')){localStorage.setItem('super-rich-mobile-hint','1');setTimeout(()=>toast('The map has more room on a PC screen. Mobile play works too.'),1500);}}catch{}if(loadWarning)toast(loadWarning);else if(state.shift)showRush();else if(state.event)showEvent();
function renderLive(){
 if(state.concept==='rich-life'){const v=ventureSummary(state),e=empireSummary(state),art=artPortfolio(state),nextOwner=[20000000,60000000,150000000][e.owned.length];$('#live-card').innerHTML=`<div class="live-card-title"><span class="live-dot"></span> PRIVATE OFFICE · My wealth, my choices</div><div class="rich-office"><button data-action="legacy" class="legacy-launch"><b>♡ Reputation · Legacy</b><small>Reputation ${Math.round(reputationSummary(state).fame).toLocaleString('en-US')} · ${reputationSummary(state).tier.name} · CH.${chapterOf(state).n}${state.ending?' · Ending reached':''}</small></button><button data-action="ventures" class="venture-launch"><b>✦ Venture Investing</b><small>${v.active.length?`${v.active.length} in review · Settling soon`:'From ₲0 up to 1,000×'}</small></button><button data-action="owners" class="owner-launch"><b>♛ Owners Club</b><small>${e.owned.length?`Reputation ${reputationSummary(state).fame} · ${reputationSummary(state).tier.name}`:`From ${money(nextOwner)} peak net worth`}</small></button><button data-action="art" class="art-launch"><b>🖼 World Masterpiece Auction</b><small>${art.owned.length?`${art.owned.length} works · ${money(art.value)}`:'From the Mona Lisa to Monet · ₲10M+'}</small></button><button data-action="invest-basket"><b>↗ Grow My Assets</b><small>₲100,000 spread investment</small></button><button data-action="mansion-design"><b>🏛 Design My Mansion</b><small>Size · Floors · Rooms · Taste</small></button><button data-action="lifestyle"><b>✦ Time to Enjoy It</b><small>Travel · Art · Yacht cruises</small></button><button data-action="stocks"><b>▥ Portfolio Check</b><small>Monthly dividends ${money(analysis.investment.dividends)}</small></button></div></div>`;return;}
 const g=chapterProgress(state),j=journeyState(state);
 $('#live-card').innerHTML=`<div class="live-card-title"><span class="live-dot"></span> CHAPTER 01 · Keys to the first workshop</div><button class="chapter-launch" data-journey="open"><b>${g.done?'What is the next find worth?':j.deal?'A deal I have not closed yet':'From a box in storage to a workshop of my own.'}</b><small>${g.done?'Workshop secured · Keep trading':Math.min(g.wins,3)+'/3 profitable deals · '+money(g.profit)+' / ₲350 profit'}</small><span>${j.deal?'Resume the deal':g.ready&&!g.done?'Get my first workshop':'Hunt the back streets'} →</span></button><div class="meter"><i style="width:${g.percent}%"></i></div><div class="live-actions"><button data-action="rush"><b>⚡ Field Rush</b><small>Budget materials and deliver orders</small></button><button data-action="projects"><b>✎ Idea Workshop</b><small>Build your own income by creating</small></button></div><button data-action="rewards" class="reward-open"><small>Optional rewards · ${rewardProviderMode(window.location.hostname)==='local-demo'?'Test mode':'Coming soon'} →</small></button>`;
}
function showRush(){
 const r=state.shift;if(!r){const result=startShift(state);if(!result.ok){toast(result.msg);return;}save();}
 const run=state.shift,orders=ordersFor(state),o=orders[run.round],canServe=run.stock>=o.stock&&run.energy>=o.energy,canCraft=state.skill>=15&&run.stock>=o.stock-1&&run.energy>=o.energy+1;
 openDialog('rush',`<div class="rush-heading"><span class="eyebrow">SIDE QUEST · Field Rush</span><h2>Choosing well beats taking everything.</h2><p>Five side jobs this month. Spend materials and focus to maximize your net pay.</p></div><div class="rush-resources"><span>▦ Materials <b>${run.stock}/${run.stockLimit||6}</b></span><span>ϟ Focus <b>${run.energy}/5</b></span><span>Pay so far <b>${money(run.earned)}</b></span></div><div class="order-queue">${orders.map((q,n)=>`<div class="${n===run.round?'current':n<run.round?'finished':''}"><span>${n<run.round?(run.results[n].pay?'✓':'—'):q.icon}</span><b>${money(q.pay)}</b><small>Materials ${q.stock} · Focus ${q.energy}</small></div>`).join('')}</div><div class="order-ticket"><span class="ticket-icon">${o.icon}</span><small>ORDER ${run.round+1} / 5</small><h3>${o.name}</h3><p>${o.text}</p><div class="ticket-price">+${money(o.pay)} <small>Net pay, materials excluded</small></div></div><div class="rush-choices"><button data-order="serve" class="primary" ${canServe?'':'disabled'}><b>Accept order</b><small>Materials ${o.stock} · Focus ${o.energy}</small></button><button data-order="craft" ${canCraft?'':'disabled'}><b>Custom build · +₲25</b><small>${state.skill<15?'Requires skill 15':'Materials '+(o.stock-1)+' · Focus '+(o.energy+1)}</small></button><button data-order="skip"><b>See the next job →</b><small>Save resources for a better one</small></button></div><p class="help">Everything settles once all five jobs are done. One run a month plus any stored tickets · Progress is saved if you close mid-run.</p>`);
}
function showProjects(){const ps=state.projects||[];openDialog('projects',`${state.concept==='rich-life'?'<span class="eyebrow">CREATIVE PATRON</span><h2>Turn your taste into a work.</h2><p>Finish films and design collections with a professional crew. Fund production, then spend creative hours on planning and directing.</p>':'<span class="eyebrow">MAKE SOMETHING. MAKE A LIVING.</span><h2>Where ideas become assets.</h2><p>Turn your ideas and creative hours into income.</p>'}<div class="project-paths">${Object.entries(PATHS).filter(([,p])=>state.concept==='rich-life'?p.richOnly:!p.richOnly).map(([id,p])=>`<button data-project="${id}"><span>${p.icon}</span><b>${p.name}</b><small>${p.tag}</small><em>${id==='flip'?'Inspect, repair and resell yourself':p.cost?money(p.cost)+' upfront':'Start with no capital'}</em></button>`).join('')}</div><h3>My Studio <small>${state.plan.create||0}h assigned this month</small></h3>${ps.filter(p=>p.status!=='archived').map(p=>`<div class="project-progress"><div><b>${esc(p.name)}</b><small>${p.status==='working'?Math.floor(p.progress)+'/'+p.hours+'h':p.status==='earning'?money(p.royalty)+'/mo · '+p.monthsLeft+' mo left':'Complete · Paid out'}</small></div><div class="meter"><i style="width:${p.progress/p.hours*100}%"></i></div>${p.status!=='working'?`<button data-archive-project="${p.id}">Archive Project</button>`:''}</div>`).join('')||'<p class="help">No projects yet. Pick your first idea.</p>'}<button data-action="creative-plan" class="primary full">Assign Creative Hours →</button><p class="help">Up to 3 in production and 8 owned. Creative hours are split evenly across active work.</p>`);}
function showProject(type){if(type==='flip'){journeyUI.show();return;}const p=PATHS[type];openDialog('project-start',`<span class="eyebrow">${p.tag}</span><h2>${p.icon} ${p.name}</h2><p>${p.desc}</p><label class="field-label">My project name<input id="project-name" maxlength="30" value="${p.name}" placeholder="What idea do you want to make?"></label><div class="project-strategies">${[['quick','Quick test','See a first result in fewer hours'],['balanced','Balanced build','A balance of time and polish'],['craft','Crafted finish','Longer to make, higher pay']].map(([style,name,desc])=>{const q=projectQuote(state,type,style);return`<button data-start-project="${type}" data-style="${style}"><b>${name} <span>${q.hours}h</span></b><small>${desc}<br>Upfront ${money(q.cost)} · Completion pay ${money(q.sale)}${q.royalty?' + '+money(q.royalty)+'/mo × 24 mo':''}</small></button>`;}).join('')}</div><p class="help">A fixed contract priced at skill ${Math.round(state.skill)}. Assign hours to finish it and the pay settles automatically. With 0 creative hours nothing progresses.</p>`);}
function showCareers(){openDialog('careers',`<span class="eyebrow">MY TIME HAS VALUE</span><h2>The first capital you earn.</h2><p>You decide your work hours. Study builds skill and opens jobs that pay more per hour.</p><div class="career-current">Current skill <b>${Math.round(state.skill)}</b> · Work this month <b>${state.plan.work}h</b></div><div class="new-options">${Object.entries(CAREERS).map(([id,c])=>`<button data-career="${id}" ${state.skill<c.skill?'disabled':''}><b>${c.icon} ${c.name} <span>${state.career===id||!state.career&&id==='flexible'?'Current job':money(c.hourly+state.skill*.09)+' / hr'}</span></b><small>${c.desc}<br>₲${(c.hourly+state.skill*.09).toFixed(2)} / hr · ${state.skill<c.skill?'Requires skill '+c.skill:'Available'}</small></button>`).join('')}</div><button data-action="creative-plan" class="primary full">Assign Work and Study Hours →</button><p class="help">Pay settles automatically each month. High stress reduces your actual income.</p>`);}
function priceChart(id){const values=[STOCKS.find(k=>k.id===id).base,...state.history.map(h=>h.prices?.[id]).filter(Number.isFinite),state.prices[id]].slice(-36),lo=Math.min(...values)*.98,hi=Math.max(...values)*1.02;const points=values.map((v,n)=>`${(n/Math.max(1,values.length-1)*280).toFixed(1)},${(48-(v-lo)/(hi-lo)*40).toFixed(1)}`).join(' ');return`<svg class="stock-chart" viewBox="0 0 280 55" role="img" aria-label="${STOCKS.find(k=>k.id===id).name} recent price trend"><path d="M0 50H280" stroke="#dce5d2"/><polyline points="${points}" fill="none" stroke="#83a569" stroke-width="2.5"/></svg>`;}
function showRewards(){
 const mode=rewardProviderMode(window.location.hostname),wallet=state.rewards,day=rewardDay(),used=wallet?.day===day?wallet.claims.length:0;
 openDialog('rewards',`<span class="eyebrow">OPTIONAL BOOST · Optional rewards</span><h2>A small boost for your next chance.</h2><p>Take a reward for in-game capital or an extra field run. Skip them entirely and work, creating, business and investing all still play in full.</p><div class="reward-notice"><b>${mode==='local-demo'?'Developer reward preview · Not a real ad':'Ad service coming soon'}</b><span>${mode==='local-demo'?'A 5-second preview screen shows how the reward flow works. No ad is served and no ad revenue is earned.':'No real ad provider is connected yet. Normal play works as usual.'}</span></div><div class="reward-wallet"><span>Stored materials <b>${wallet?.materials||0}</b></span><span>Extra tickets <b>${wallet?.tickets||0}</b></span><span>Rewards taken today <b>${used}/3</b></span></div><div class="reward-options">${Object.entries(REWARDS).map(([kind,r])=>{const status=rewardStatus(state,kind,day);return`<section><div class="reward-option-title"><span>${r.icon}</span><div><h3>${r.name}</h3><b>${r.label}</b></div></div><p>${r.description}</p><button data-reward="${kind}" ${mode!=='local-demo'||!status.ok?'disabled':''}>${!status.ok?'Not available right now':mode==='local-demo'?'Watch 5s and claim '+r.label:'Ads coming soon'}</button>${!status.ok?`<small>${status.msg}</small>`:''}</section>`;}).join('')}</div><p class="help">Each reward is once a day by your device local date. You can store one material pack and one ticket. Materials apply at the start of your next field run; tickets are used automatically once the monthly run is done.</p><div class="game-only-note">All capital, rewards and investment results are in-game only.<br>They cannot be withdrawn as cash or gift cards, or transferred to anyone.</div><button data-action="close" class="full">Keep Playing Without Rewards</button>`);
}
function beginReward(kind){
 if(rewardSession)return;
 if(rewardProviderMode(window.location.hostname)!=='local-demo'){toast('No real ad service is connected yet.');return;}
 const status=rewardStatus(state,kind);if(!status.ok){toast(status.msg);showRewards();return;}
 const r=REWARDS[kind];rewardSession=createDemoSession({id:crypto.randomUUID(),kind,day:rewardDay()});
 openDialog('reward-preview',`<span class="eyebrow">TEST PREVIEW · Not a real ad</span><h2>${r.name} reward preview</h2><p>Finish the preview and <b>${r.label}</b> lands in your game. Close it early and nothing is granted, with no penalty to your play.</p><div class="reward-preview-art"><span>${r.icon}</span><b>A small boost for your idea</b><small>A developer preview with no external ad and no ad revenue</small></div><div class="reward-progress"><i id="reward-progress-fill"></i></div><p id="reward-countdown" class="reward-countdown" role="status">5s left</p><button data-action="close" class="full">Skip and Return to the Game</button><p class="help">The preview only advances while this screen is visible. Game time pauses meanwhile.</p>`);
}
function advanceReward(dt){
 if(!rewardSession||modal!=='reward-preview')return;
 rewardSession.advance(dt*1000,!document.hidden);
 const remaining=rewardSession.remaining;
 $('#reward-progress-fill').style.width=((5000-remaining)/50)+'%';
 const label=Math.ceil(remaining/1000)+'s left';if($('#reward-countdown').textContent!==label)$('#reward-countdown').textContent=label;
 const receipt=rewardSession.complete();if(!receipt)return;rewardSession=null;
 const result=grantReward(state,receipt);changed();
 if(!result.ok){toast(result.msg);showRewards();return;}
 audio.play('win');renderer.burst(analysis.owned[0]?.i??-1,REWARDS[receipt.kind].label+' claimed');
 openDialog('reward-result',`<div class="rush-result"><span>${REWARDS[receipt.kind].icon}</span><p>Test reward granted</p><h2>${REWARDS[receipt.kind].label}</h2><p>${REWARDS[receipt.kind].description}</p><button data-action="close" class="primary full">Use It in Game →</button><button data-action="rewards" class="full">View Stash</button><p class="help">In-game rewards only; they cannot be cashed out or transferred.</p></div>`);
}
function renderRichOverview(){const goal=RICH_GOALS.find(m=>analysis.wealth<m.wealth),growth=analysis.wealth-(state.startingWealth||2000000),passive=analysis.passive+analysis.investment.dividends;$('#side-content').innerHTML=`<section class="side-section"><h3>My Portfolio Performance</h3>${row('Net worth change since start',(growth>=0?'+':'')+money(growth))}${row('Total return',((analysis.wealth/(state.startingWealth||2000000)-1)*100).toFixed(2)+'%')}${row('Rental net income + dividends',money(passive)+' / mo')}<p class="help">Net worth change includes investment P&L along with living and experience spending.</p><button class="portfolio-link" data-action="stocks">Check Stock Weighting and Dividends →</button><button class="portfolio-link" data-action="portfolio">Run My ${analysis.owned.length} Rental Properties →</button></section>${chapterCard(state,analysis)}${rivalCard(state,analysis.wealth)}<section class="side-section"><h3>Next Wealth Goal</h3><div class="milestone-title"><b>${goal?.name||'Legacy Maker achieved'}</b><span>${goal?money(goal.wealth):'✦'}</span></div><div class="meter milestone"><i style="width:${goal?Math.max(0,Math.min(100,analysis.wealth/goal.wealth*100)):100}%"></i></div><p class="help">${goal?money(Math.max(0,goal.wealth-analysis.wealth))+' to go':'Keep growing your empire and your lifestyle.'}</p></section><section class="side-section"><h3>How I Enjoyed It</h3>${row('My collection',flexState(state).owned.length+' / 3')}${row('Special memories',(state.lifestyle?.memories||0)+'')}${row('Travel, culture & cruise spend',money(state.lifestyle?.spent||0))}<button class="portfolio-link" data-action="lifestyle">Pick My Next Experience →</button></section><section class="advisor"><div class="advisor-avatar">✦</div><div><b>${analysis.net>=0?'You may not work, but your assets do.':'Review your spending and asset mix.'}</b><p>Projected cash flow this month ${money(analysis.net)}. Invest it or spend it on yourself: your call.</p></div></section>`;}
function owners(){openDialog('growth',empireDialog(state,analysis.wealth));}
import {assetSaleReport} from './engine.js';
